            } else {
                let mut forwardIp = ip;
                let mut step: c_int = 1;
                let mut searchMatchNb: c_int = acceleration << LZ4_skipTrigger;
                loop {
                    let h1 = forwardH;
                    let current: U32 = forwardIp.offset_from(base) as c_long as U32;
                    let mut matchIndex = LZ4_getIndexOnHash(
                        h1,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *const c_void,
                        tableType,
                    );
                    ip = forwardIp;
                    forwardIp = forwardIp.offset(step as isize);
                    let cur = searchMatchNb;
                    searchMatchNb += 1;
                    step = cur >> LZ4_skipTrigger;
                    if forwardIp > mflimitPlusOne {
                        break 'main;
                    }

                    if using_dict_ctx {
                        if matchIndex < startIndex {
                            matchIndex = LZ4_getIndexOnHash(
                                h1,
                                &raw const (*dictCtx).hashTable as *const LZ4_u32 as *const c_void,
                                byU32,
                            );
                            match_0 = dictBase.offset(matchIndex as isize);
                            matchIndex = matchIndex.wrapping_add(dictDelta);
                            lowLimit = dictionary;
                        } else {
                            match_0 = base.offset(matchIndex as isize);
                            lowLimit = source as *const BYTE;
                        }
                    } else if using_ext_dict {
                        if matchIndex < startIndex {
                            match_0 = dictBase.offset(matchIndex as isize);
                            lowLimit = dictionary;
                        } else {
                            match_0 = base.offset(matchIndex as isize);
                            lowLimit = source as *const BYTE;
                        }
                    } else {
                        match_0 = base.offset(matchIndex as isize);
                    }

                    forwardH = LZ4_hashPosition(forwardIp as *const c_void, tableType);
                    LZ4_putIndexOnHash(
                        current,
                        h1,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *mut c_void,
                        tableType,
                    );

                    if dict_small && matchIndex < prefixIdxLimit {
                        continue;
                    }
                    if (!by_u16 || LZ4_DISTANCE_MAX < LZ4_DISTANCE_ABSOLUTE_MAX)
                        && matchIndex.wrapping_add(LZ4_DISTANCE_MAX as U32) < current
                    {
                        continue;
                    }
                    if LZ4_read32(match_0 as *const c_void) != LZ4_read32(ip as *const c_void) {
                        continue;
                    }
                    if maybe_extMem {
                        offset = current.wrapping_sub(matchIndex);
                    }
                    break;
                }
            }

            filledIp = ip;

            if match_0 > lowLimit && *ip.offset(-1) == *match_0.offset(-1) {
                loop {
                    ip = ip.offset(-1);
                    match_0 = match_0.offset(-1);
                    if !((ip > anchor)
                        && (match_0 > lowLimit)
                        && (*ip.offset(-1) == *match_0.offset(-1)))
                    {
                        break;
                    }
                }
            }

            let litLength: c_uint = ip.offset_from(anchor) as c_long as c_uint;
            token = op;
            op = op.offset(1);

            if limited_output
                && op
                    .offset(litLength as isize)
                    .offset((2 + 1 + 5) as isize)
                    .offset(litLength.wrapping_div(255) as isize)
                    > olimit
            {
                return 0;
            }

            if fill_output
                && op
                    .offset(litLength.wrapping_add(240).wrapping_div(255) as isize)
                    .offset(litLength as isize)
                    .offset(2)
                    .offset(1)
                    .offset(12)
                    .offset(-4)
                    > olimit
            {
                op = op.offset(-1);
                break;
            }

            if litLength >= RUN_MASK {
                let mut len = litLength.wrapping_sub(RUN_MASK);
                *token = (RUN_MASK << ML_BITS) as BYTE;
                while len >= 255 {
                    *op = 255 as BYTE;
                    op = op.offset(1);
                    len = len.wrapping_sub(255);
                }
                *op = len as BYTE;
                op = op.offset(1);
            } else {
                *token = (litLength << ML_BITS) as BYTE;
            }

            LZ4_wildCopy8(
                op as *mut c_void,
                anchor as *const c_void,
                op.offset(litLength as isize) as *mut c_void,
            );
            op = op.offset(litLength as isize);

            loop {
                if fill_output
                    && op.offset(2).offset(1).offset(MFLIMIT as isize).offset(-(MINMATCH as isize))
                        > olimit
                {
                    op = token;
                    break 'main;
                }

                if maybe_extMem {
                    LZ4_writeLE16(op as *mut c_void, offset as U16);
                    op = op.offset(2);
                } else {
                    LZ4_writeLE16(op as *mut c_void, ip.offset_from(match_0) as c_long as U16);
                    op = op.offset(2);
                }

                let mut matchCode: c_uint;
                if (using_ext_dict || using_dict_ctx) && lowLimit == dictionary {
                    let mut limit = ip.offset(dictEnd.offset_from(match_0) as c_long as isize);
                    if limit > matchlimit {
                        limit = matchlimit;
                    }
                    matchCode = LZ4_count(
                        ip.offset(MINMATCH as isize),
                        match_0.offset(MINMATCH as isize),
                        limit,
                    );
                    ip = ip.offset((matchCode as size_t).wrapping_add(MINMATCH as size_t) as isize);
                    if ip == limit {
                        let more = LZ4_count(limit, source as *const BYTE, matchlimit) as c_uint;
                        matchCode = matchCode.wrapping_add(more);
                        ip = ip.offset(more as isize);
                    }
                } else {
                    matchCode = LZ4_count(
                        ip.offset(MINMATCH as isize),
                        match_0.offset(MINMATCH as isize),
                        matchlimit,
                    );
                    ip = ip.offset((matchCode as size_t).wrapping_add(MINMATCH as size_t) as isize);
                }

                if outputDirective as c_uint != 0
                    && op
                        .offset((1 + 5) as isize)
                        .offset(matchCode.wrapping_add(240).wrapping_div(255) as isize)
                        > olimit
                {
                    if fill_output {
                        let newMatchCode: U32 = ((15 - 1) as U32).wrapping_add(
                            (olimit.offset_from(op) as c_long as U32)
                                .wrapping_sub(1)
                                .wrapping_sub(LASTLITERALS as U32)
                                .wrapping_mul(255),
                        );
                        ip = ip.offset(-((matchCode as U32).wrapping_sub(newMatchCode) as isize));
                        matchCode = newMatchCode as c_uint;
                        if ip <= filledIp {
                            let mut ptr = ip;
                            while ptr <= filledIp {
                                let h2 = LZ4_hashPosition(ptr as *const c_void, tableType) as U32;
                                LZ4_clearHash(
                                    h2,
                                    &raw mut (*cctx).hashTable as *mut LZ4_u32 as *mut c_void,
                                    tableType,
                                );
                                ptr = ptr.offset(1);
                            }
                        }
                    } else {
                        return 0;
                    }
                }

                if matchCode >= ML_MASK {
                    *token = (*token as c_uint).wrapping_add(ML_MASK) as BYTE;
                    matchCode = matchCode.wrapping_sub(ML_MASK);
                    LZ4_write32(op as *mut c_void, 0xffffffff);
                    while matchCode >= (4 * 255) as c_uint {
                        op = op.offset(4);
                        LZ4_write32(op as *mut c_void, 0xffffffff);
                        matchCode = matchCode.wrapping_sub((4 * 255) as c_uint);
                    }
                    op = op.offset(matchCode.wrapping_div(255) as isize);
                    *op = matchCode.wrapping_rem(255) as BYTE;
                    op = op.offset(1);
                } else {
                    *token = (*token as c_int + matchCode as BYTE as c_int) as BYTE;
                }

                anchor = ip;
                if ip >= mflimitPlusOne {
                    break 'main;
                }

                let h3 = LZ4_hashPosition(ip.offset(-2) as *const c_void, tableType) as U32;
                if by_ptr {
                    LZ4_putPositionOnHash(
                        ip.offset(-2),
                        h3,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *mut c_void,
                        byPtr,
                    );
                } else {
                    let idx = ip.offset(-2).offset_from(base) as c_long as U32;
                    LZ4_putIndexOnHash(
                        idx,
                        h3,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *mut c_void,
                        tableType,
                    );
                }

                if by_ptr {
                    match_0 = LZ4_getPosition(
                        ip,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *const c_void,
                        tableType,
                    );
                    LZ4_putPosition(
                        ip,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *mut c_void,
                        tableType,
                    );
                    if !(match_0.offset(LZ4_DISTANCE_MAX as isize) >= ip
                        && LZ4_read32(match_0 as *const c_void) == LZ4_read32(ip as *const c_void))
                    {
                        break;
                    }
                    token = op;
                    op = op.offset(1);
                    *token = 0;
                } else {
                    let h4 = LZ4_hashPosition(ip as *const c_void, tableType) as U32;
                    let current0 = ip.offset_from(base) as c_long as U32;
                    let mut matchIndex0 = LZ4_getIndexOnHash(
                        h4,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *const c_void,
                        tableType,
                    );

                    if using_dict_ctx {
                        if matchIndex0 < startIndex {
                            matchIndex0 = LZ4_getIndexOnHash(
                                h4,
                                &raw const (*dictCtx).hashTable as *const LZ4_u32 as *const c_void,
                                byU32,
                            );
                            match_0 = dictBase.offset(matchIndex0 as isize);
                            lowLimit = dictionary;
                            matchIndex0 = matchIndex0.wrapping_add(dictDelta);
                        } else {
                            match_0 = base.offset(matchIndex0 as isize);
                            lowLimit = source as *const BYTE;
                        }
                    } else if using_ext_dict {
                        if matchIndex0 < startIndex {
                            match_0 = dictBase.offset(matchIndex0 as isize);
                            lowLimit = dictionary;
                        } else {
                            match_0 = base.offset(matchIndex0 as isize);
                            lowLimit = source as *const BYTE;
                        }
                    } else {
                        match_0 = base.offset(matchIndex0 as isize);
                    }

                    LZ4_putIndexOnHash(
                        current0,
                        h4,
                        &raw mut (*cctx).hashTable as *mut LZ4_u32 as *mut c_void,
                        tableType,
                    );

                    let valid_dict = if dict_small {
                        matchIndex0 >= prefixIdxLimit
                    } else {
                        true
                    };
                    let valid_dist = if by_u16 && LZ4_DISTANCE_MAX == LZ4_DISTANCE_ABSOLUTE_MAX {
                        true
                    } else {
                        matchIndex0.wrapping_add(LZ4_DISTANCE_MAX as U32) >= current0
                    };

                    if !(valid_dict
                        && valid_dist
                        && LZ4_read32(match_0 as *const c_void) == LZ4_read32(ip as *const c_void))
                    {
                        break;
                    }

                    token = op;
                    op = op.offset(1);
                    *token = 0;
                    if maybe_extMem {
                        offset = current0.wrapping_sub(matchIndex0);
                    }
                }
            }

            ip = ip.offset(1);
            forwardH = LZ4_hashPosition(ip as *const c_void, tableType);
        }
    }

    let mut lastRun: size_t = iend.offset_from(anchor) as c_long as size_t;
    if outputDirective as c_uint != 0
        && op
            .offset(lastRun as isize)
            .offset(1)
            .offset(
                lastRun
                    .wrapping_add(255)
                    .wrapping_sub(RUN_MASK as size_t)
                    .wrapping_div(255) as isize,
            )
            > olimit
    {
        if fill_output {
            lastRun = (olimit.offset_from(op) as c_long as size_t).wrapping_sub(1);
            lastRun = lastRun.wrapping_sub(
                lastRun
                    .wrapping_add(256)
                    .wrapping_sub(RUN_MASK as size_t)
                    .wrapping_div(256),
            );
        } else {
            return 0;
        }
    }

    if lastRun >= RUN_MASK as size_t {
        let mut accumulator = lastRun.wrapping_sub(RUN_MASK as size_t);
        *op = (RUN_MASK << ML_BITS) as BYTE;
        op = op.offset(1);
        while accumulator >= 255 {
            *op = 255 as BYTE;
            op = op.offset(1);
            accumulator = accumulator.wrapping_sub(255);
        }
        *op = accumulator as BYTE;
        op = op.offset(1);
    } else {
        *op = (lastRun << ML_BITS) as BYTE;
        op = op.offset(1);
    }

    // SAFETY: `anchor..anchor+lastRun` and `op..op+lastRun` are valid non-overlapping ranges by the function's validated preconditions and prior output bound checks.
    unsafe {
        ::libc::memcpy(
            op as *mut c_void,
            anchor as *const c_void,
            lastRun as ::libc::size_t,
        );
    }
    ip = anchor.offset(lastRun as isize);
    op = op.offset(lastRun as isize);

    if fill_output {
        *inputConsumed = (ip as *const c_char).offset_from(source) as c_long as c_int;
    }

    (op as *mut c_char).offset_from(dest) as c_long as c_int
}
